import { getMDXComponent, getMDXExport as getMDXExportBase } from "mdx-bundler/client";
import { useMemo } from "react";

import cn from "@diegofrayo-pkg/cn";
import type UtilsTypes from "@diegofrayo-pkg/types";
import type ReactTypes from "@diegofrayo-pkg/types/react";
import { isString } from "@diegofrayo-pkg/validator";

import { BoxWithTitle, CopyToClipboardPopover, ImageWithLink, SourceCode } from "~/components/common";
import {
	Blockquote,
	Box,
	Button,
	Code,
	Collapsible,
	Icon,
	InlineText,
	Link,
	List,
	Paragraph,
	Separator,
	Title,
} from "~/components/primitive";
import { ButtonVariants } from "~/components/primitive/button";
import { CodeVariants } from "~/components/primitive/code";
import { type ImageProps } from "~/components/primitive/image";
import { LinkVariants } from "~/components/primitive/link";
import { ListVariants } from "~/components/primitive/list";
import { SeparatorVariants } from "~/components/primitive/separator";
import { TitleVariants, type TitleProps } from "~/components/primitive/title";

import styles from "./styles.module.css";

type MDXContentProps = {
	code: string;
	components?: UtilsTypes.Object;
	globals?: UtilsTypes.Object;
};

export function MDXContent({
	code,
	components = {},
	globals = {},
}: MDXContentProps): ReactTypes.JSXElement {
	const Component = useMemo(() => getMDXComponent(code, globals), [code, globals]);

	return (
		<Box className={cn("dr-mdx-content", styles["dr-mdx-content"])}>
			{/* eslint-disable-next-line react-hooks/static-components */}
			<Component components={{ ...MDXComponents, ...components }} />
		</Box>
	);
}

// NOTE: mdx-bundler ships broken types for this function (`ExportedObject` is undeclared), so the return type is set here
export function getMDXExport(code: string): UtilsTypes.Object<string> {
	return getMDXExportBase(code) as UtilsTypes.Object<string>;
}

// --- CONSTANTS ---

// DOCS: https://mdxjs.com/table-of-components
const MDXComponents = {
	// --- PRIMITIVE COMPONENTS ---
	a: function CustomA({
		children,
		href,
	}: ReactTypes.DOM.HTMLElementAttributes["a"]): ReactTypes.JSXElement {
		return (
			<Link
				href={href || ""}
				variant={LinkVariants.STYLED}
				isExternalLink
			>
				{children}
			</Link>
		);
	},
	blockquote: Blockquote,
	code: function CustomCode({
		children,
	}: ReactTypes.DOM.HTMLElementAttributes["code"]): ReactTypes.JSXElement {
		if (isString(children)) {
			return (
				<CopyToClipboardPopover textToCopy={children}>
					<Button variant={ButtonVariants.SMOOTH}>
						<Code variant={CodeVariants.STYLED}>{children}</Code>
					</Button>
				</CopyToClipboardPopover>
			);
		}

		throw new Error("Code component: Invalid children");
	},
	h1: createTitleComponent("h1", { className: "text-3xl md:text-5xl" }),
	h2: createTitleComponent("h2", { className: "text-2xl md:text-4xl" }),
	h3: createTitleComponent("h3", { className: "text-xl md:text-3xl" }),
	h4: createTitleComponent("h4", { className: "text-lg md:text-2xl" }),
	hr: function CustomHr(): ReactTypes.JSXElement {
		return <Separator variant={SeparatorVariants.DASHED} />;
	},
	li: List.Item,
	p: Paragraph,
	pre: function CustomPre({
		children,
	}: ReactTypes.DOM.HTMLElementAttributes["pre"]): ReactTypes.JSXElement {
		return <SourceCode code={children} />;
	},
	ul: function CustomUl({
		children,
	}: ReactTypes.DOM.HTMLElementAttributes["ul"]): ReactTypes.JSXElement {
		return <List variant={ListVariants.SIMPLE}>{children}</List>;
	},

	// --- CUSTOM COMPONENTS ---
	Box,
	BoxWithTitle,
	Collapsible,
	Icon,
	InlineText,
	Link,
	MDXImage: (props: ImageProps): ReactTypes.JSXElement => {
		return (
			<ImageWithLink
				className="shadow-md shadow-zinc-900"
				{...props}
			/>
		);
	},
	SourceCode,
	Separator,
};

// --- UTILS ---

function createTitleComponent(Tag: "h1" | "h2" | "h3" | "h4", props: Omit<TitleProps, "as">) {
	return function CustomTitle({
		children,
	}: ReactTypes.DOM.HTMLElementAttributes["h1"]): ReactTypes.JSXElement {
		return (
			<Title
				{...props}
				as={Tag}
				variant={TitleVariants.STYLED}
			>
				{children}
			</Title>
		);
	};
}

